(function(root){
'use strict';
const personLabel=value=>({主角:'Lead',重要配角:'Major supporting character',配角:'Supporting character',反派:'Antagonist',男:'Male',女:'Female',非二元:'Nonbinary',未设定:'Unspecified'})[value]||value;
root.storyContentView=function(p,tab,{E,btn,icon,personExtension,chapterNext,personNext,chapterActions,chapterFooterNote,chapterCover}){
 const a=p.agent,C=root.StoryContent;C.ensure(p);
 const footer=(label,target)=>`<footer class="as-content-footer"><span>Edits are saved locally</span>${btn(label+' '+icon('arrow'),'planning-tab','primary',`data-tab="${target}"`)}</footer>`;
 const empty=(scope,title,text)=>`<section class="as-content-empty">${icon(scope==='characters'?'person':'book')}<h2>${title}</h2><p>${text}</p>${btn(icon('spark')+'Generate '+(scope==='characters'?'character profiles':'chapters'),'content-generate','primary',`data-scope="${scope}"`)}<small>Try the sample or add content manually.</small></section>`;
 if(tab==='characters'){
 const c=p.characters.find(x=>x.id===a.selectedCharacter),idx=p.characters.indexOf(c);
 const field=(key,label,placeholder,rows=3)=>`<label class="as-content-field">${label}<textarea data-content-scope="characters" data-content-id="${c.id}" data-content-field="${key}" rows="${rows}" placeholder="${placeholder}">${E(c[key]||'')}</textarea></label>`;
 const input=(key,label,type='text')=>`<label>${label}<input type="${type}" ${key==='age'?'min="0" max="9999"':''} data-content-scope="characters" data-content-id="${c.id}" data-content-field="${key}" value="${E(c[key]||'')}" placeholder="Enter ${label.toLowerCase()}"></label>`;
 const select=(key,label,values)=>`<label>${label}<select data-content-scope="characters" data-content-id="${c.id}" data-content-field="${key}"><option value="">Select an option</option>${[...new Set([...values,...(c[key]?[c[key]]:[])])].map(x=>`<option value="${E(x)}" ${c[key]===x?'selected':''}>${E(personLabel(x))}</option>`).join('')}</select></label>`;
 return `<div class="as-content-layout as-people-layout"><div>${c&&personExtension?personExtension.tabs(c):''}${c&&personExtension?.active==='assets'?personExtension.view(c):c?`<section class="as-person-editor" aria-label="Edit character profile"><div class="as-content-heading"><h2>Character profile</h2><div class="as-row"><span>Character ${idx+1} / ${p.characters.length}</span>${btn('Remove character','content-remove','',`data-scope="characters" data-id="${c.id}"`)}</div></div><div class="as-person-basics">${input('name','Name')}${input('age','Age','number')}${select('role','Role',['主角','重要配角','配角','反派'])}${select('gender','Gender',['男','女','非二元','未设定'])}</div>${field('identity','Identity','Occupation, social role, or other defining identity',2)}<label class="as-content-field">Personality<input data-content-scope="characters" data-content-id="${c.id}" data-content-field="personality" value="${E(c.personality||c.personalityTags?.join('、')||'')}" placeholder="Separate traits with commas, e.g. reserved, curious, dependable"></label>${field('background','Backstory','History, motivation, goals, and connection to the conflict',7)}${field('appearance','Appearance','Build, clothing, and distinctive features (optional)')}${field('signature','Signature behavior','Habits, speech patterns, or gestures (optional)')}${field('belongings','Belongings and rules','Key props and limits on their use (optional)')}${field('arc','Character arc','Key choices and how the character changes (optional)')}${field('relation','Relationships','Relationships, conflicts, and emotional changes (optional)')}</section>`:empty('characters','Add your story characters','Generate profiles from the synopsis or add your first character manually.')}<p class="as-content-autosave">Edits are saved locally</p></div><aside class="as-people-rail as-flow-rail" aria-label="Character list"><div class="as-content-heading"><h3>Characters</h3><span>${p.characters.length} ${p.characters.length===1?'character':'characters'}</span></div><div class="as-people-grid as-flow-rail-list">${p.characters.map((person,i)=>btn(`<strong data-person-name="${person.id}">${E(person.name||'Untitled character')}</strong><span data-person-role="${person.id}">${E(personLabel(person.role)||'Needs details')}</span>${personExtension?`<small>${E(personExtension.status(person))}</small>`:''}`,'content-select','as-person-tile '+(person.id===a.selectedCharacter?'active':''),`data-scope="characters" data-id="${person.id}" aria-label="Select character ${E(person.name||i+1)}" aria-pressed="${person.id===a.selectedCharacter}"`)).join('')}</div><div class="as-flow-rail-actions">${btn(icon('person')+'Add character','content-add','as-add-chapter','data-scope="characters"')}${btn((personNext?.label||'Continue to chapters')+' '+icon('arrow'),'planning-tab','primary',`data-tab="${personNext?.tab||'chapters'}"`)}<p>Character profiles are saved automatically.</p></div></aside></div>`;
 }
 if(tab==='chapters'){
 const count=text=>String(text||'').replace(/\s/g,'').length;
 const downloadable=p.storyChapters.some(c=>c.body.trim());
 const download=()=>btn('Download chapters (TXT)','chapters-download',chapterActions?'':'primary',downloadable?'':'disabled');
 const projectSummary = p.video ? `<div class="vp-chapter-project">
   <span class="vp-chapter-cover">${chapterCover ? `<img src="${E(chapterCover)}" alt="">` : icon('book')}</span>
   <strong class="vp-chapter-project-title">${E(a.planning.title||'Untitled project')}</strong>
 </div>` : '';
 const chapterLink = (chapter, index) => {
   const number = `<span class="as-chapter-no">Chapter ${index+1}</span>`;
   const title = `<strong data-chapter-title="${E(chapter.id)}">${E(chapter.title||'Untitled chapter')}</strong>`;
   const wordCount = `<span data-chapter-words="${E(chapter.id)}">${count(chapter.body)} ${p.video ? 'chars' : 'characters'}</span>`;
   const selected = chapter.id===a.selectedChapter;
   const contents = p.video
     ? `<span class="vp-chapter-link-icon">${icon('book')}</span>${number}${wordCount}`
     : number+title+wordCount;
   const accessibleName = p.video ? '' : `aria-label="Go to chapter ${index+1}: ${E(chapter.title)}"`;
   return btn(contents,'chapter-locate','as-chapter-link '+(selected?'active':''),`data-id="${E(chapter.id)}" ${accessibleName} aria-current="${selected?'location':'false'}"`);
 };
 const chapterCount = (chapter) => `<span data-chapter-count="${chapter.id}">${count(chapter.body)} characters</span>`;
 return `<div class="as-content-layout as-chapters-layout"><div class="as-all-chapters">${p.storyChapters.length?p.storyChapters.map((c,idx)=>`<section class="as-chapter-editor" id="story-chapter-${E(c.id)}" data-chapter-section="${E(c.id)}" aria-label="Edit chapter ${idx+1}"><div class="as-content-heading"><h2>Chapter ${idx+1}</h2><div class="as-row">${btn(p.video ? '<span class="revise-slider" aria-hidden="true"><svg class="revise-arrow" viewBox="0 0 18 18"><path d="M2 9h14M9 3l6 6-6 6" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round" stroke-dasharray=".1 4"/></svg><svg class="revise-pencil" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linejoin="round"><path d="m4 16 9-9 4 4-9 9-5 1zM11 9l4 4M18 2l1.2 3.2L22 6.5l-2.8 1.2L18 11l-1.2-3.3L14 6.5l2.8-1.3z"/></svg></span><span class="revise-label">Revise chapter</span>' : icon('spark')+'Revise chapter','chapter-ai-edit',p.video?'as-chapter-ai revise-chapter':'as-chapter-ai',`data-id="${c.id}" aria-label="Revise chapter ${idx+1} with AI" ${c.body.trim()?'':'disabled'}`)}${p.video ? btn('<svg aria-hidden="true" viewBox="0 0 24 24" width="17" height="17" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round"><path d="M3 6h18M9 6V3h6v3M6 6l1 15h10l1-15M10 10v7M14 10v7"/></svg>','content-remove','chapter-icon-action',`data-scope="chapters" data-id="${c.id}" aria-label="Remove chapter ${idx+1}" title="Remove chapter"`) : `${btn(icon('spark')+'Fill with AI','content-generate','as-chapter-ai',`data-scope="chapters" data-id="${c.id}" aria-label="Fill missing text in chapter ${idx+1} with AI" title="Fill missing text in this chapter"`)}${btn('Remove','content-remove','as-chapter-ai',`data-scope="chapters" data-id="${c.id}" aria-label="Remove chapter ${idx+1}"`)}${btn('Move up','chapter-move','',`data-id="${c.id}" data-offset="-1" ${idx===0?'disabled':''}`)}${btn('Move down','chapter-move','',`data-id="${c.id}" data-offset="1" ${idx===p.storyChapters.length-1?'disabled':''}`)}`}</div></div><label class="as-chapter-title">${p.video ? '' : 'Chapter title'}<input aria-label="Chapter ${idx+1} title" data-content-scope="chapters" data-content-id="${c.id}" data-content-field="title" placeholder="Enter a chapter title" value="${E(c.title)}">${p.video ? `<span class="as-chapter-title-edit" title="Edit chapter title">${icon('edit')}</span>` : ''}</label><div class="as-chapter-body-heading"><label for="chapter-body-${E(c.id)}">Story text</label>${p.video ? '' : chapterCount(c)}</div>${p.video ? '<div class="as-chapter-body-row">' : ''}<textarea id="chapter-body-${E(c.id)}" aria-label="Chapter ${idx+1} story text" class="as-chapter-body" data-content-scope="chapters" data-content-id="${c.id}" data-content-field="body" placeholder="Start with the first scene. Describe the action, dialogue, and what happens next.">${E(c.body)}</textarea>${p.video ? `${chapterCount(c)}</div>` : ''}</section>`).join(''):empty('chapters','Write your first chapter','Develop chapters from your synopsis and character profiles. Read and edit them here.')}<p class="as-content-autosave">Edits are saved locally</p></div><aside class="as-chapter-rail as-flow-rail${p.video?' vp-chapter-card':''}" aria-label="Chapters"><div class="as-content-heading"><h3>Chapters</h3><span>${p.storyChapters.length} ${p.storyChapters.length===1?'chapter':'chapters'}</span></div>${projectSummary}<div class="as-flow-rail-list">${p.storyChapters.map(chapterLink).join('')}</div><div class="sw-chapter-rail-actions as-flow-rail-actions">${btn(icon('book')+'Add chapter','content-add','as-add-chapter','data-scope="chapters"')}${chapterActions||''}${chapterFooterNote||'<p>Chapter edits are saved automatically.</p>'}</div></aside></div>`;
 }
 return '';
};
})(globalThis);
